mapper.select:
SELECT P.PRODUCT_ID, P.CATEGORY_ID, C.CATEGORY_NM, P.PRODUCT_NM, P.PRICE, P.STATUS_CD, NVL(S.STOCK_QTY, 0) AS STOCK_QTY FROM TB_PRODUCT P JOIN TB_CATEGORY C ON C.CATEGORY_ID = P.CATEGORY_ID LEFT JOIN TB_STOCK S ON S.PRODUCT_ID = P.PRODUCT_ID
AND P.CATEGORY_ID = #{categoryId}
AND UPPER(P.PRODUCT_NM) LIKE '%' || UPPER(#{productNm}) || '%'
AND P.STATUS_CD = #{statusCd}
ORDER BY P.PRODUCT_ID

SELECT PRODUCT_ID, PRODUCT_NM, PRICE, CATEGORY_NM, STOCK_QTY
  FROM VW_PRODUCT_STOCK
 WHERE PRODUCT_ID = #{productId}

mapper.update:
UPDATE TB_STOCK
   SET STOCK_QTY = STOCK_QTY - #{qty},
       UPD_DT    = SYSDATE
 WHERE PRODUCT_ID = #{productId}
   AND WAREHOUSE_CD = 'W01'
   AND STOCK_QTY >= #{qty}
